/**
 * Excel import wizard.
 *
 * Drop the original "Margin Management" workbook in, preview the rows the
 * parser extracted, and commit them as a batch of sales / fuel_deliveries /
 * derived-margin files in the data repo.
 */
import { useMemo, useRef, useState } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import {
  AlertTriangle,
  CheckCircle2,
  FileSpreadsheet,
  Loader2,
  Upload,
} from "lucide-react";

import { api } from "@/lib/api";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import {
  parseWorkbook,
  groupRowsByDate,
  type ImportPreview,
  type ImportedDayRow,
} from "@/lib/excel-import";
import { recomputeAndSaveMargin } from "@/lib/derived";
import type {
  FuelDeliveriesFile,
  FuelDeliveryRecord,
  FuelGradesConfig,
  SalesFile,
  TaxConstants,
} from "@/lib/types";
import { formatCAD } from "@/lib/utils";

export default function ExcelImportPage() {
  const qc = useQueryClient();
  const inputRef = useRef<HTMLInputElement>(null);
  const [preview, setPreview] = useState<ImportPreview | null>(null);
  const [fileName, setFileName] = useState<string | null>(null);
  const [parsing, setParsing] = useState(false);
  const [committing, setCommitting] = useState(false);
  const [progress, setProgress] = useState<{ done: number; total: number } | null>(null);

  const gradesQ = useQuery({
    queryKey: ["config", "fuel_grades"],
    queryFn: () => api.readData<FuelGradesConfig>("config/fuel_grades.json"),
  });
  const taxesQ = useQuery({
    queryKey: ["config", "taxes"],
    queryFn: () => api.readData<TaxConstants>("config/taxes.json"),
  });

  const grades = gradesQ.data?.data?.grades ?? [];

  async function handleFile(file: File) {
    setParsing(true);
    setPreview(null);
    setFileName(file.name);
    try {
      const buf = await file.arrayBuffer();
      const result = parseWorkbook(buf, { grades });
      setPreview(result);
      if (result.rows.length === 0) {
        toast.warning("No rows could be parsed -- check the column headers in your workbook.");
      } else {
        toast.success(`Parsed ${result.rows.length} day-grade rows from ${file.name}.`);
      }
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Failed to parse workbook");
    } finally {
      setParsing(false);
    }
  }

  async function commit() {
    if (!preview || !gradesQ.data?.data) return;
    const gradesCfg = gradesQ.data.data;
    const taxes = taxesQ.data?.data;
    const byDate = groupRowsByDate(preview.rows);
    const dates = Array.from(byDate.keys()).sort();
    setCommitting(true);
    setProgress({ done: 0, total: dates.length });
    let succeeded = 0;
    let failed = 0;
    try {
      for (const date of dates) {
        const rowsForDate = byDate.get(date) ?? [];
        try {
          await writeOneDay({ date, rowsForDate, gradesCfg, taxes });
          succeeded += 1;
        } catch (err) {
          console.error(`Failed to import ${date}:`, err);
          failed += 1;
        }
        setProgress({ done: succeeded + failed, total: dates.length });
      }
      qc.invalidateQueries();
      toast.success(`Imported ${succeeded} day(s)${failed > 0 ? ` (${failed} failed)` : ""}.`);
      setPreview(null);
      setFileName(null);
    } finally {
      setCommitting(false);
      setProgress(null);
    }
  }

  const summary = useMemo(() => {
    if (!preview) return null;
    const dates = new Set(preview.rows.map((r) => r.date));
    const totalSales = preview.rows.reduce((s, r) => s + r.bullochSalesCAD, 0);
    const totalVolume = preview.rows.reduce((s, r) => s + r.bullochVolumeL, 0);
    const totalDeliveryL = preview.rows.reduce((s, r) => s + (r.purchaseL ?? 0), 0);
    return {
      dayCount: dates.size,
      rowCount: preview.rows.length,
      totalSales,
      totalVolume,
      totalDeliveryL,
    };
  }, [preview]);

  return (
    <div className="space-y-6">
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <FileSpreadsheet className="h-5 w-5" /> Import from Excel
          </CardTitle>
          <CardDescription>
            Upload your existing "Margin Management" workbook (one sheet per fuel grade) to back-fill
            historical sales, deliveries, and margins in a single batch. The importer auto-detects
            the date / sales / volume / inventory columns by header text.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          {grades.length === 0 ? (
            <div className="flex items-start gap-2 rounded-md border border-amber-300/40 bg-amber-50/30 p-3 text-sm dark:border-amber-900/40 dark:bg-amber-950/20">
              <AlertTriangle className="mt-0.5 h-4 w-4 text-amber-600 dark:text-amber-400" />
              <p>Configure fuel grades in the Fuel grades tab first -- the importer needs them to map sheets to grades.</p>
            </div>
          ) : null}
          <div className="flex flex-wrap items-center gap-3">
            <input
              ref={inputRef}
              type="file"
              accept=".xlsx,.xls,.xlsm,.csv"
              onChange={(e) => {
                const f = e.target.files?.[0];
                if (f) handleFile(f);
              }}
              className="hidden"
            />
            <Button
              variant="outline"
              onClick={() => inputRef.current?.click()}
              disabled={parsing || committing || grades.length === 0}
            >
              {parsing ? (
                <Loader2 className="h-4 w-4 animate-spin" />
              ) : (
                <Upload className="h-4 w-4" />
              )}
              Choose .xlsx file
            </Button>
            {fileName ? (
              <span className="text-sm text-muted-foreground">{fileName}</span>
            ) : null}
          </div>
        </CardContent>
      </Card>

      {preview && summary ? (
        <Card>
          <CardHeader>
            <CardTitle>Preview</CardTitle>
            <CardDescription>
              Verify the parser picked up the right columns. Nothing is written until you click
              Import below.
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-6">
            <div className="grid grid-cols-2 gap-3 md:grid-cols-4">
              <Metric label="Days" value={summary.dayCount.toLocaleString("en-CA")} />
              <Metric label="Rows (day x grade)" value={summary.rowCount.toLocaleString("en-CA")} />
              <Metric label="Total sales" value={formatCAD(summary.totalSales)} />
              <Metric
                label="Total volume"
                value={`${summary.totalVolume.toLocaleString("en-CA", { maximumFractionDigits: 0 })} L`}
              />
            </div>

            <div>
              <div className="mb-2 text-sm font-medium">Sheet detection</div>
              <div className="space-y-1.5">
                {preview.sheetSummaries.map((s) => (
                  <div
                    key={s.sheetName}
                    className="flex items-center justify-between rounded-md border bg-card/40 px-3 py-2 text-sm"
                  >
                    <div className="flex items-center gap-2">
                      {s.detectedGradeId ? (
                        <CheckCircle2 className="h-4 w-4 text-emerald-500" />
                      ) : (
                        <AlertTriangle className="h-4 w-4 text-amber-500" />
                      )}
                      <span className="font-medium">{s.sheetName}</span>
                      {s.detectedGradeId ? (
                        <Badge variant="outline">{s.detectedGradeId}</Badge>
                      ) : (
                        <span className="text-muted-foreground">no grade match</span>
                      )}
                    </div>
                    <div className="text-xs text-muted-foreground">
                      {s.rowsParsed} parsed
                      {s.rowsSkipped > 0 ? ` / ${s.rowsSkipped} skipped` : ""}
                      {s.firstDate ? ` (${s.firstDate} -> ${s.lastDate})` : ""}
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {preview.warnings.length > 0 ? (
              <div className="space-y-1.5">
                <div className="text-sm font-medium text-amber-600 dark:text-amber-400">Warnings</div>
                {preview.warnings.map((w, i) => (
                  <div
                    key={i}
                    className="rounded-md border border-amber-300/40 bg-amber-50/30 px-3 py-2 text-xs dark:border-amber-900/40 dark:bg-amber-950/20"
                  >
                    {w}
                  </div>
                ))}
              </div>
            ) : null}

            <Separator />

            <div>
              <div className="mb-2 text-sm font-medium">First 10 rows</div>
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead>
                    <tr className="text-xs uppercase tracking-wide text-muted-foreground">
                      <th className="px-2 py-1 text-left">Date</th>
                      <th className="px-2 py-1 text-left">Grade</th>
                      <th className="px-2 py-1 text-right">Sales $</th>
                      <th className="px-2 py-1 text-right">Volume L</th>
                      <th className="px-2 py-1 text-right">EOD inv L</th>
                      <th className="px-2 py-1 text-right">Purchase L</th>
                      <th className="px-2 py-1 text-right">Cost $/L</th>
                    </tr>
                  </thead>
                  <tbody className="number-tabular">
                    {preview.rows.slice(0, 10).map((r, i) => (
                      <tr key={i} className="border-t">
                        <td className="px-2 py-1">{r.date}</td>
                        <td className="px-2 py-1">{r.gradeId}</td>
                        <td className="px-2 py-1 text-right">{r.bullochSalesCAD.toFixed(2)}</td>
                        <td className="px-2 py-1 text-right">{r.bullochVolumeL.toFixed(2)}</td>
                        <td className="px-2 py-1 text-right">{r.eodInventoryL?.toFixed(2) ?? "-"}</td>
                        <td className="px-2 py-1 text-right">{r.purchaseL?.toFixed(2) ?? "-"}</td>
                        <td className="px-2 py-1 text-right">{r.productCostExTaxPerL?.toFixed(4) ?? "-"}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>

            <div className="flex flex-col items-end gap-2">
              {progress ? (
                <p className="text-xs text-muted-foreground">
                  Importing… {progress.done} / {progress.total}
                </p>
              ) : null}
              <Button
                onClick={commit}
                disabled={committing || preview.rows.length === 0}
                size="lg"
              >
                {committing ? <Loader2 className="h-4 w-4 animate-spin" /> : <Upload className="h-4 w-4" />}
                Import {summary.dayCount} day(s) into mkrgas-data
              </Button>
            </div>
          </CardContent>
        </Card>
      ) : null}
    </div>
  );
}

interface WriteOneDayArgs {
  date: string;
  rowsForDate: ImportedDayRow[];
  gradesCfg: FuelGradesConfig;
  taxes: TaxConstants | undefined;
}

async function writeOneDay({ date, rowsForDate, gradesCfg, taxes }: WriteOneDayArgs) {
  // 1. Build the sales file by aggregating all grade rows for this date.
  const salesPayload: SalesFile = {
    date,
    fuel: rowsForDate.map((r) => ({
      gradeId: r.gradeId,
      bullochSalesCAD: r.bullochSalesCAD,
      bullochVolumeL: r.bullochVolumeL,
      eodInventoryL: r.eodInventoryL,
    })),
    store: {
      generalCAD: 0,
      tobaccoCAD: 0,
      alcoholCAD: 0,
      lotteryInCAD: 0,
      lotteryOutCAD: 0,
      otherCAD: 0,
    },
    card: { debitCAD: 0, creditCAD: 0 },
    cashFloatCAD: 0,
    bankDepositCAD: 0,
    submittedBy: "excel-import",
    submittedAt: new Date().toISOString(),
    notes: "Imported from Excel workbook",
  };
  const existingSales = await api.readData<SalesFile>(`sales/${date}.json`);
  await api.writeData(`sales/${date}.json`, salesPayload, existingSales.sha ?? null, `import: sales ${date}`);

  // 2. If any row has a purchase, write a fuel_deliveries file.
  const deliveries: FuelDeliveryRecord[] = rowsForDate
    .filter((r) => (r.purchaseL ?? 0) > 0)
    .map((r) => ({
      id: crypto.randomUUID(),
      gradeId: r.gradeId,
      invoiceNo: r.invoiceNo ?? "imported",
      purchaseVolumeL: r.purchaseL ?? 0,
      productCostExTaxPerL: r.productCostExTaxPerL ?? 0,
      deliveryCostPerL: r.deliveryCostPerL ?? 0,
      recordedBy: "excel-import",
      recordedAt: new Date().toISOString(),
    }));
  let deliveryFile: FuelDeliveriesFile | null = null;
  if (deliveries.length > 0) {
    deliveryFile = { date, entries: deliveries };
    const existingDel = await api.readData<FuelDeliveriesFile>(`fuel_deliveries/${date}.json`);
    await api.writeData(
      `fuel_deliveries/${date}.json`,
      deliveryFile,
      existingDel.sha ?? null,
      `import: deliveries ${date}`,
    );
  }

  // 3. Recompute and persist the derived margin snapshot for this date.
  await recomputeAndSaveMargin({
    date,
    gradesCfg,
    taxes: taxes ?? {
      fetPerL: 0,
      pftPerL: 0,
      carbonPerL: 0,
      urbanPerL: 0,
      rebatePerL: 0,
      gstPct: 0,
      pstPct: 0,
      hstPct: 0,
    },
    sales: salesPayload,
    delivery: deliveryFile,
  });
}

function Metric({ label, value }: { label: string; value: string }) {
  return (
    <div className="rounded-md border bg-card/50 px-3 py-2.5">
      <div className="text-xs uppercase tracking-wide text-muted-foreground">{label}</div>
      <div className="number-tabular text-base font-semibold">{value}</div>
    </div>
  );
}
