/**
 * Receipt photo uploader.
 *
 * Lets the cashier snap or pick a photo of the Bulloch tape / deposit slip,
 * downscales it client-side to a sane size, encodes as a data URL, and
 * appends it to the day's SalesFile. Stays entirely on the client until
 * the EoD report is submitted, at which point the worker writes the JSON
 * (with the embedded base64) to the data repo.
 */
import { useRef, useState } from "react";
import { Camera, ImageIcon, Trash2, X } from "lucide-react";
import { toast } from "sonner";

import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import type { ReceiptAttachment } from "@/lib/types";

const MAX_WIDTH_PX = 1200;
const JPEG_QUALITY = 0.78;
const SOFT_LIMIT_BYTES = 350 * 1024;

async function downscaleImage(file: File): Promise<Blob> {
  if (file.size <= SOFT_LIMIT_BYTES && file.type === "image/jpeg") return file;
  const bitmap = await createImageBitmap(file).catch(() => null);
  if (!bitmap) return file;
  const ratio = Math.min(1, MAX_WIDTH_PX / Math.max(bitmap.width, 1));
  const w = Math.round(bitmap.width * ratio);
  const h = Math.round(bitmap.height * ratio);
  const canvas = document.createElement("canvas");
  canvas.width = w;
  canvas.height = h;
  const ctx = canvas.getContext("2d");
  if (!ctx) return file;
  ctx.drawImage(bitmap, 0, 0, w, h);
  return await new Promise<Blob>((resolve) => {
    canvas.toBlob(
      (b) => resolve(b ?? file),
      "image/jpeg",
      JPEG_QUALITY,
    );
  });
}

function blobToDataUrl(blob: Blob): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(reader.error ?? new Error("File read failed"));
    reader.onload = () => resolve(reader.result as string);
    reader.readAsDataURL(blob);
  });
}

interface Props {
  receipts: ReceiptAttachment[] | undefined;
  username: string;
  onChange: (next: ReceiptAttachment[]) => void;
}

export function ReceiptUploader({ receipts, username, onChange }: Props) {
  const list = receipts ?? [];
  const fileRef = useRef<HTMLInputElement>(null);
  const cameraRef = useRef<HTMLInputElement>(null);
  const [busy, setBusy] = useState(false);
  const [preview, setPreview] = useState<ReceiptAttachment | null>(null);

  async function handleFiles(files: FileList | null) {
    if (!files || files.length === 0) return;
    setBusy(true);
    try {
      const next: ReceiptAttachment[] = [];
      for (const f of Array.from(files)) {
        if (!f.type.startsWith("image/")) {
          toast.error(`${f.name}: not an image`);
          continue;
        }
        const blob = await downscaleImage(f);
        const dataUrl = await blobToDataUrl(blob);
        next.push({
          id: crypto.randomUUID(),
          name: f.name,
          dataUrl,
          mimeType: "image/jpeg",
          sizeBytes: blob.size,
          addedAt: new Date().toISOString(),
          addedBy: username,
        });
      }
      onChange([...list, ...next]);
      if (next.length > 0) toast.success(`Attached ${next.length} receipt(s).`);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Failed to read image");
    } finally {
      setBusy(false);
    }
  }

  function remove(id: string) {
    onChange(list.filter((r) => r.id !== id));
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle>Receipt photos</CardTitle>
        <CardDescription>
          Snap a photo of the Bulloch tape, deposit slip, or anything else worth keeping. Images
          are downscaled to ~1200px JPEG before being saved with the day's report.
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-3">
        <input
          ref={fileRef}
          type="file"
          accept="image/*"
          multiple
          className="hidden"
          onChange={(e) => handleFiles(e.target.files)}
        />
        <input
          ref={cameraRef}
          type="file"
          accept="image/*"
          capture="environment"
          className="hidden"
          onChange={(e) => handleFiles(e.target.files)}
        />
        <div className="flex flex-wrap items-center gap-2">
          <Button
            variant="outline"
            onClick={() => cameraRef.current?.click()}
            disabled={busy}
          >
            <Camera className="h-4 w-4" /> Take photo
          </Button>
          <Button
            variant="outline"
            onClick={() => fileRef.current?.click()}
            disabled={busy}
          >
            <ImageIcon className="h-4 w-4" /> Choose image
          </Button>
        </div>
        {list.length === 0 ? (
          <p className="text-xs text-muted-foreground">No receipts attached yet.</p>
        ) : (
          <div className="grid grid-cols-2 gap-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6">
            {list.map((r) => (
              <div
                key={r.id}
                className="group relative overflow-hidden rounded-md border bg-card/40"
              >
                <button
                  type="button"
                  className="block aspect-square w-full"
                  onClick={() => setPreview(r)}
                  title={r.name}
                >
                  <img
                    src={r.dataUrl}
                    alt={r.name}
                    className="h-full w-full object-cover transition-transform group-hover:scale-105"
                    loading="lazy"
                  />
                </button>
                <div className="absolute inset-x-0 bottom-0 flex items-center justify-between bg-gradient-to-t from-black/70 to-transparent px-2 py-1 text-[10px] text-white">
                  <span className="truncate">{(r.sizeBytes / 1024).toFixed(0)} KB</span>
                  <Button
                    size="icon"
                    variant="ghost"
                    onClick={() => remove(r.id)}
                    className="h-6 w-6 text-white hover:bg-white/20"
                  >
                    <Trash2 className="h-3.5 w-3.5" />
                  </Button>
                </div>
              </div>
            ))}
          </div>
        )}
      </CardContent>
      {preview ? (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 p-4"
          onClick={() => setPreview(null)}
        >
          <div className="relative max-h-full max-w-3xl">
            <Button
              variant="ghost"
              size="icon"
              className="absolute -top-12 right-0 text-white hover:bg-white/20"
              onClick={(e) => {
                e.stopPropagation();
                setPreview(null);
              }}
            >
              <X className="h-5 w-5" />
            </Button>
            <img
              src={preview.dataUrl}
              alt={preview.name}
              className="max-h-[85vh] max-w-full rounded-md"
            />
          </div>
        </div>
      ) : null}
    </Card>
  );
}
