/**
 * Tiny inline trend line for KPI cards.
 *
 * Renders an ECharts line with no axes, no grid lines, no tooltips, and
 * (optionally) a soft area fill in the same hue as the stroke. Designed to
 * sit next to or under a big number without competing for attention.
 */
import { EChart } from "@/charts/EChart";

interface SparklineProps {
  data: Array<number | null>;
  color?: string;
  height?: number;
  showArea?: boolean;
  showLast?: boolean;
}

export function Sparkline({
  data,
  color = "#10b981",
  height = 36,
  showArea = true,
  showLast = false,
}: SparklineProps) {
  const cleanData = data.map((v) => (Number.isFinite(v) ? Number(v) : null));
  const option = {
    grid: { left: 0, right: 0, top: 2, bottom: 2 },
    tooltip: { show: false },
    xAxis: { type: "category", show: false, boundaryGap: false },
    yAxis: { type: "value", show: false, scale: true },
    series: [
      {
        type: "line",
        smooth: true,
        showSymbol: showLast,
        symbolSize: 5,
        symbol: "circle",
        sampling: "lttb",
        itemStyle: { color },
        lineStyle: { width: 1.6, color },
        ...(showArea
          ? {
              areaStyle: {
                opacity: 0.22,
                color: {
                  type: "linear",
                  x: 0,
                  y: 0,
                  x2: 0,
                  y2: 1,
                  colorStops: [
                    { offset: 0, color },
                    { offset: 1, color: "transparent" },
                  ],
                },
              },
            }
          : {}),
        emphasis: { disabled: true },
        data: cleanData,
      },
    ],
  };
  return <EChart option={option} height={height} />;
}
