/**
 * Fuel margin engine -- reproduces "Margin Managmenet by day for 3 months 2024.xlsx"
 * column-for-column (cells G, H, D, J, K, L, N and the M40/N42/N43 monthly rollups).
 *
 * All quantities are in Liters and CAD. Pure functions only -- the same code
 * runs in the browser and inside the Cloudflare Worker.
 */

/** Tax configuration mirroring Excel cells Q10..Q17. */
export interface TaxConfig {
  /** Federal Excise Tax, $/L (Excel Q10) */
  fetPerL: number;
  /** Provincial Fuel Tax, $/L (Excel Q11) */
  pftPerL: number;
  /** Carbon tax, $/L (Excel Q12) */
  carbonPerL: number;
  /** Urban / transit surcharge, $/L (Excel Q13) */
  urbanPerL: number;
  /** Tax rebate, $/L. Added back. (Excel Q14) */
  rebatePerL: number;
  /** GST rate in percent (Excel Q15) */
  gstPct: number;
  /** PST rate in percent (Excel Q16) */
  pstPct: number;
  /** HST rate in percent; when > 0, replaces GST+PST (Excel Q17) */
  hstPct: number;
}

export const ZERO_TAX_CONFIG: TaxConfig = {
  fetPerL: 0,
  pftPerL: 0,
  carbonPerL: 0,
  urbanPerL: 0,
  rebatePerL: 0,
  gstPct: 0,
  pstPct: 0,
  hstPct: 0,
};

/**
 * Net sell price $/L excluding all taxes (Excel column K).
 *
 *   if HST > 0:   pump / (1 + HST/100) - FET - PFT - Carbon - Urban + Rebate
 *   else:         pump / (1 + GST/100 + PST/100) - FET - PFT - Carbon - Urban + Rebate
 */
export function netSellPricePerL(pumpPricePerL: number, tax: TaxConfig): number {
  if (!Number.isFinite(pumpPricePerL) || pumpPricePerL <= 0) return 0;
  const consumptionTaxes = tax.fetPerL + tax.pftPerL + tax.carbonPerL + tax.urbanPerL;
  const divisor = tax.hstPct > 0 ? 1 + tax.hstPct / 100 : 1 + tax.gstPct / 100 + tax.pstPct / 100;
  return pumpPricePerL / divisor - consumptionTaxes + tax.rebatePerL;
}

/**
 * Average pump price $/L (Excel column J).
 *
 *   J = I / M = bullochSales$ / bullochVolumeL
 */
export function avgPumpPricePerL(bullochSalesCAD: number, bullochVolumeL: number): number {
  if (bullochVolumeL <= 0) return 0;
  return bullochSalesCAD / bullochVolumeL;
}

/**
 * Rolling weighted-average product cost $/L including delivery (Excel column H).
 *
 * Recurrence:
 *   if purchaseL > 0:
 *     H_t = (D_{t-1} * H_{t-1} + purchaseL * G_t) / (D_{t-1} + purchaseL)
 *   else:
 *     H_t = H_{t-1}    (carry forward when there is no delivery)
 *
 * where G_t = product cost ex-tax $/L + delivery cost $/L  (Excel column G).
 */
export function rollingAvgCost(
  prevInventoryL: number,
  prevRollingAvg: number,
  purchaseL: number,
  newProductCostInclDelivery: number,
): number {
  if (purchaseL <= 0) return prevRollingAvg;
  const denom = prevInventoryL + purchaseL;
  if (denom <= 0) return newProductCostInclDelivery;
  return (prevInventoryL * prevRollingAvg + purchaseL * newProductCostInclDelivery) / denom;
}

/**
 * End-of-day inventory L (Excel column D).
 *
 *   D_t = D_{t-1} - bullochVolumeL_t + purchaseL_t
 */
export function eodInventoryL(
  prevInventoryL: number,
  bullochVolumeL: number,
  purchaseL: number,
): number {
  return prevInventoryL - bullochVolumeL + purchaseL;
}

/** State carried day-to-day for a single fuel grade. */
export interface GradeState {
  inventoryL: number;
  rollingAvgCost: number;
}

/** Yellow input cells for one day for one grade. Any may be omitted when unknown. */
export interface DailyInputs {
  /** Excel B - invoice # (informational) */
  invoiceNo?: string;
  /** Excel C - purchase volume L (0 / undefined if no delivery) */
  purchaseL?: number;
  /** Excel E - invoice unit price $/L excluding all taxes */
  productCostExTaxPerL?: number;
  /** Excel F - delivery cost $/L (already converted from $/100L) */
  deliveryCostPerL?: number;
  /** Excel I - Bulloch POS daily sales $ */
  bullochSalesCAD?: number;
  /** Excel M - Bulloch POS daily sales L */
  bullochVolumeL?: number;
}

/** All green (computed) cells for one day for one grade. */
export interface DailyMargin {
  /** Excel G - product cost $/L including delivery */
  productCostInclDelivery: number;
  /** Excel H - rolling-average product cost $/L */
  rollingAvgCost: number;
  /** Excel D - end-of-day inventory L */
  eodInventoryL: number;
  /** Excel J - avg daily pump price $/L (tax-inclusive) */
  avgPumpPrice: number;
  /** Excel K - net sell price $/L (tax-stripped) */
  netSellPrice: number;
  /** Excel L - associate margin $/L = K - H */
  associateMargin: number;
  /** Excel N - gross profit $ = L * M */
  grossProfit: number;
  /** Whether the day had any Bulloch sales recorded */
  hasSales: boolean;
  /** Whether the day had a fuel delivery */
  hasDelivery: boolean;
}

/**
 * Compute one day of metrics for one grade given the previous day's state.
 * Returns both the daily metrics and the new state to carry to the next day.
 *
 * Edge cases that mirror the workbook:
 *  - If no purchase and no sales, the row is essentially blank but the state
 *    still carries forward unchanged.
 *  - If there is a purchase but no sale that day, inventory grows, rolling avg
 *    updates, but margin / gross profit are 0 (we treat them as "n/a").
 *  - If there is a sale but no purchase, rolling avg carries forward.
 */
export function computeDailyMargin(
  prev: GradeState,
  inputs: DailyInputs,
  tax: TaxConfig,
): { metrics: DailyMargin; next: GradeState } {
  const purchaseL = inputs.purchaseL ?? 0;
  const productCostExTax = inputs.productCostExTaxPerL ?? 0;
  const deliveryCost = inputs.deliveryCostPerL ?? 0;
  const bullochSales = inputs.bullochSalesCAD ?? 0;
  const bullochVolume = inputs.bullochVolumeL ?? 0;

  const hasDelivery = purchaseL > 0;
  const hasSales = bullochVolume > 0 && bullochSales > 0;

  const productCostInclDelivery = hasDelivery
    ? productCostExTax + deliveryCost
    : prev.rollingAvgCost;

  const newRollingAvg = rollingAvgCost(
    prev.inventoryL,
    prev.rollingAvgCost,
    purchaseL,
    productCostInclDelivery,
  );

  const newInventory = eodInventoryL(prev.inventoryL, bullochVolume, purchaseL);

  const avgPump = avgPumpPricePerL(bullochSales, bullochVolume);
  const netSell = hasSales ? netSellPricePerL(avgPump, tax) : 0;
  const margin = hasSales ? netSell - newRollingAvg : 0;
  const grossProfit = hasSales ? margin * bullochVolume : 0;

  return {
    metrics: {
      productCostInclDelivery,
      rollingAvgCost: newRollingAvg,
      eodInventoryL: newInventory,
      avgPumpPrice: avgPump,
      netSellPrice: netSell,
      associateMargin: margin,
      grossProfit,
      hasSales,
      hasDelivery,
    },
    next: {
      inventoryL: newInventory,
      rollingAvgCost: newRollingAvg,
    },
  };
}

/** Monthly rollup mirroring Excel cells M40 / N42 / N43. */
export interface MonthlyRollup {
  totalLiters: number;
  totalGrossProfit: number;
  /** = totalGrossProfit / totalLiters  (Excel: rolling-avg weighted margin) */
  rollingAvgWeightedMargin: number;
  /** = mean(associateMargin) over days with sales (Excel: avg daily margin) */
  avgDailyMargin: number;
}

/**
 * Compute the monthly rollup from per-day metrics paired with the day's
 * Bulloch sales volume in liters.
 *
 *   M40 = totalLiters             = Σ bullochVolumeL on days with sales
 *   N42 = rollingAvgWeightedMargin = Σ grossProfit / Σ bullochVolumeL
 *   N43 = avgDailyMargin           = mean(associateMargin) over days with sales
 */
export function rollupMonthWithVolumes(
  rows: { metrics: DailyMargin; bullochVolumeL: number }[],
): MonthlyRollup {
  let totalL = 0;
  let totalGP = 0;
  let marginSum = 0;
  let salesDays = 0;
  for (const r of rows) {
    if (!r.metrics.hasSales) continue;
    totalL += r.bullochVolumeL;
    totalGP += r.metrics.grossProfit;
    marginSum += r.metrics.associateMargin;
    salesDays += 1;
  }
  return {
    totalLiters: totalL,
    totalGrossProfit: totalGP,
    rollingAvgWeightedMargin: totalL > 0 ? totalGP / totalL : 0,
    avgDailyMargin: salesDays > 0 ? marginSum / salesDays : 0,
  };
}

/**
 * Convenience helper to chain `computeDailyMargin` across a series of days
 * for a single grade.
 */
export function computeSeries(
  opening: GradeState,
  series: DailyInputs[],
  tax: TaxConfig,
): {
  daily: DailyMargin[];
  rollup: MonthlyRollup;
  finalState: GradeState;
} {
  let state = { ...opening };
  const daily: DailyMargin[] = [];
  const withVolumes: { metrics: DailyMargin; bullochVolumeL: number }[] = [];
  for (const day of series) {
    const { metrics, next } = computeDailyMargin(state, day, tax);
    daily.push(metrics);
    withVolumes.push({ metrics, bullochVolumeL: day.bullochVolumeL ?? 0 });
    state = next;
  }
  return {
    daily,
    rollup: rollupMonthWithVolumes(withVolumes),
    finalState: state,
  };
}
