import { useEffect, useMemo, useState } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import { Calendar, Loader2, Plus, Save, Trash2 } from "lucide-react";

import { api } from "@/lib/api";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useAuth } from "@/lib/auth-store";
import { isoWeek } from "@/lib/utils";
import type { SchedulesFile, ShiftEntry } from "@/lib/types";

function dateOfIsoWeek(isoYearWeek: string): Date {
  const [y, wk] = isoYearWeek.split("-W").map(Number);
  const simple = new Date(Date.UTC(y, 0, 1 + (wk - 1) * 7));
  const dow = simple.getUTCDay();
  const monday = new Date(simple);
  if (dow <= 4) monday.setUTCDate(simple.getUTCDate() - simple.getUTCDay() + 1);
  else monday.setUTCDate(simple.getUTCDate() + 8 - simple.getUTCDay());
  return monday;
}

function weekDates(isoYearWeek: string): string[] {
  const monday = dateOfIsoWeek(isoYearWeek);
  return Array.from({ length: 7 }).map((_, i) => {
    const d = new Date(monday);
    d.setUTCDate(monday.getUTCDate() + i);
    return d.toISOString().slice(0, 10);
  });
}

export default function SchedulePage() {
  const user = useAuth((s) => s.user)!;
  const qc = useQueryClient();
  const [week, setWeek] = useState(isoWeek());
  const days = useMemo(() => weekDates(week), [week]);
  const [file, setFile] = useState<SchedulesFile>({ week, shifts: [] });
  const [saving, setSaving] = useState(false);

  const q = useQuery({
    queryKey: ["schedule", week],
    queryFn: () => api.readData<SchedulesFile>(`schedules/${week}.json`),
  });

  useEffect(() => {
    if (q.data?.exists && q.data.data) setFile(q.data.data);
    else setFile({ week, shifts: [] });
  }, [week, q.data?.exists, q.data?.data]);

  const shiftsByDay = useMemo(() => {
    const m: Record<string, ShiftEntry[]> = {};
    for (const d of days) m[d] = [];
    for (const s of file.shifts) {
      if (m[s.date]) m[s.date].push(s);
    }
    return m;
  }, [days, file.shifts]);

  const isAdmin = user.role === "admin";

  function addShift(date: string) {
    setFile((f) => ({
      ...f,
      shifts: [
        ...f.shifts,
        {
          id: crypto.randomUUID(),
          employeeId: "",
          employeeName: "",
          date,
          startTime: "08:00",
          endTime: "16:00",
          role: "cashier",
        },
      ],
    }));
  }

  function updateShift(id: string, patch: Partial<ShiftEntry>) {
    setFile((f) => ({
      ...f,
      shifts: f.shifts.map((s) => (s.id === id ? { ...s, ...patch } : s)),
    }));
  }

  function removeShift(id: string) {
    setFile((f) => ({ ...f, shifts: f.shifts.filter((s) => s.id !== id) }));
  }

  async function save() {
    setSaving(true);
    try {
      await api.writeData(
        `schedules/${week}.json`,
        { ...file, week },
        q.data?.sha ?? null,
        `schedule for ${week}`,
      );
      toast.success("Schedule saved");
      qc.invalidateQueries({ queryKey: ["schedule"] });
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Failed to save");
    } finally {
      setSaving(false);
    }
  }

  return (
    <div className="space-y-6">
      <header className="flex flex-wrap items-end justify-between gap-4">
        <div>
          <Badge variant="secondary" className="mb-2">
            <Calendar className="mr-1 h-3 w-3" /> Weekly schedule
          </Badge>
          <h1 className="text-3xl font-semibold tracking-tight">Schedule</h1>
          <p className="text-sm text-muted-foreground">
            {isAdmin ? "Plan shifts for the week." : "Your team's shifts for the week."}
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Label className="text-xs text-muted-foreground">Week</Label>
          <Input
            value={week}
            onChange={(e) => setWeek(e.target.value)}
            placeholder="YYYY-Www"
            className="w-32"
          />
        </div>
      </header>

      {q.isLoading ? (
        <div className="flex items-center gap-2 text-sm text-muted-foreground">
          <Loader2 className="h-4 w-4 animate-spin" /> Loading…
        </div>
      ) : null}

      <div className="grid gap-3 md:grid-cols-7">
        {days.map((d) => {
          const date = new Date(`${d}T00:00:00Z`);
          return (
            <Card key={d} className="min-h-[260px]">
              <CardHeader className="p-3 pb-2">
                <CardTitle className="text-sm">
                  {date.toLocaleDateString("en-CA", { weekday: "short", day: "2-digit", month: "short" })}
                </CardTitle>
                <CardDescription className="text-[11px]">{d}</CardDescription>
              </CardHeader>
              <CardContent className="space-y-2 p-3 pt-1">
                {shiftsByDay[d].map((s) => (
                  <div
                    key={s.id}
                    className="space-y-1 rounded-md border bg-card/40 p-2 text-xs"
                  >
                    {isAdmin ? (
                      <>
                        <Input
                          value={s.employeeName}
                          onChange={(e) =>
                            updateShift(s.id, { employeeName: e.target.value })
                          }
                          placeholder="Employee"
                          className="h-7 text-xs"
                        />
                        <div className="flex gap-1">
                          <Input
                            type="time"
                            value={s.startTime}
                            onChange={(e) =>
                              updateShift(s.id, { startTime: e.target.value })
                            }
                            className="h-7 text-xs"
                          />
                          <Input
                            type="time"
                            value={s.endTime}
                            onChange={(e) =>
                              updateShift(s.id, { endTime: e.target.value })
                            }
                            className="h-7 text-xs"
                          />
                        </div>
                        <div className="flex gap-1">
                          <Select
                            value={s.role}
                            onValueChange={(v) => updateShift(s.id, { role: v })}
                          >
                            <SelectTrigger className="h-7 text-xs">
                              <SelectValue />
                            </SelectTrigger>
                            <SelectContent>
                              <SelectItem value="cashier">Cashier</SelectItem>
                              <SelectItem value="manager">Manager</SelectItem>
                              <SelectItem value="cleaning">Cleaning</SelectItem>
                            </SelectContent>
                          </Select>
                          <Button
                            variant="ghost"
                            size="icon"
                            className="h-7 w-7"
                            onClick={() => removeShift(s.id)}
                          >
                            <Trash2 className="h-3 w-3" />
                          </Button>
                        </div>
                      </>
                    ) : (
                      <div>
                        <div className="font-medium">{s.employeeName || "Unassigned"}</div>
                        <div className="text-muted-foreground">
                          {s.startTime}–{s.endTime} · {s.role}
                        </div>
                      </div>
                    )}
                  </div>
                ))}
                {isAdmin ? (
                  <Button
                    variant="ghost"
                    size="sm"
                    className="w-full"
                    onClick={() => addShift(d)}
                  >
                    <Plus className="h-3 w-3" /> Add shift
                  </Button>
                ) : null}
              </CardContent>
            </Card>
          );
        })}
      </div>

      {isAdmin ? (
        <div className="flex justify-end">
          <Button size="lg" disabled={saving} onClick={save}>
            {saving ? <Loader2 className="h-4 w-4 animate-spin" /> : <Save className="h-4 w-4" />}
            Save schedule
          </Button>
        </div>
      ) : null}
    </div>
  );
}
